#!/usr/bin/env python3
"""
Round 106b tiles patch (28 September 2026), beside round106b_culprits.py.

  attacks/*.geojson  new: the owner's Attacks On Activists collection as map
                     layers - Global Witness's killings one by one, Land of
                     Resistance, Front Line Defenders, CIMI's and the Pastoral
                     Land Commission's case lists, Caci, the Public Agencies Map
                     of Conflicts, slave labour by state, police stations
                     (OpenStreetMap). attacks/build.json says how each was read
                     and placed.

Whole files (stored compressed here), written only where they differ. Run from
the repository root.
"""
import base64, gzip, pathlib

FILES = {'attacks/build.json': '', 'attacks/caci_indigenous.geojson': '', 'attacks/cimi_indigenous_violence.geojson': '', 'attacks/cpt_massacres.geojson': '', 'attacks/cpt_slave_labour_by_state.geojson': '', 'attacks/cpt_threatened_2000_2011.geojson': '', 'attacks/cpt_violence_tables.geojson': '', 'attacks/frontline_cases.geojson': '', 'attacks/gw_killings.geojson': '', 'attacks/land_of_resistance.geojson': '', 'attacks/police_stations_osm.geojson': '', 'attacks/public_agencies_conflicts.geojson': ''}

if not pathlib.Path("scripts").is_dir():
    raise SystemExit("round106b: scripts/ not found; run from the culprits-tiles-more root")
changed = []
for path, b64 in FILES.items():
    p = pathlib.Path(path)
    new = gzip.decompress(base64.b64decode(b64))
    if p.exists() and p.read_bytes() == new:
        continue
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(new)
    changed.append(path)
print("round106b: " + (", ".join(changed) if changed else "nothing to change (already applied)"))
